#pragma once
// ============================================================================
// engine_event_dto.h — Structured Engine Telemetry DTO
// ============================================================================
// ARCHITECTURAL RULE: This header must NEVER include Qt, Eigen, Physics, or
// any Solver types. Only standard library types are allowed.
// Timestamps are generated by the driver, never by the GUI.
// ============================================================================

#include <string>
#include <cstdint>

namespace acutesim {
namespace compute {
namespace orchestration {

struct EngineEventDTO {
    enum class Type : int {
        Info        = 0,
        Warning     = 1,
        Error       = 2,
        Convergence = 3
    };

    Type        type      = Type::Info;
    std::string message;
    uint64_t    timestamp = 0;   // Unix epoch millis, driver-generated
    std::string source;          // e.g. "LocalWorkerDriver", "BatchExecutionEngine"
};

} // namespace orchestration
} // namespace compute
} // namespace acutesim
